// Dump returns diagnostic information about the connection pool state.
func (p *connPool) Dump() interface{} {
	poolInfo := make(map[string]interface{})
	poolInfo["size"] = p.size
	poolInfo["remoteService"] = p.remoteService

	connections := make(map[string]interface{})
	p.conns.Range(func(key, value interface{}) bool {
		addr := key.(string)
		trans := value.(*transports)
		connInfo := make(map[string]interface{})
		connInfo["poolSize"] = trans.size
		connInfo["currentIndex"] = atomic.LoadUint32(&trans.index)

		activeCount := 0
		for _, ct := range trans.cliTransports {
			if ct != nil {
				if isActive, ok := ct.(grpc.IsActive); ok && isActive.IsActive() {
					activeCount++
				}
			}
		}
		connInfo["activeConnections"] = activeCount
		connections[addr] = connInfo
		return true
	})
	poolInfo["connections"] = connections

	return poolInfo
}

